<?php
require_once __DIR__ . '/../includes/bootstrap.php';$pageTitle='Suppliers';$activePage='suppliers/index.php';$basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$act=$_POST['action']??'';if($act==='save'){$id=(int)($_POST['supplier_id']??0);$name=trim((string)($_POST['supplier_name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));if($name==='')throw new RuntimeException('Supplier name is required.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');if($id){$s=$pdo->prepare('UPDATE suppliers SET supplier_name=?,phone=?,email=?,address=? WHERE supplier_id=?');$s->execute([$name,$phone?:null,$email?:null,$address?:null,$id]);flash('success','Supplier updated.');}else{$s=$pdo->prepare('INSERT INTO suppliers(supplier_name,phone,email,address) VALUES(?,?,?,?)');$s->execute([$name,$phone?:null,$email?:null,$address?:null]);flash('success','Supplier added.');}}elseif($act==='delete'){$s=$pdo->prepare('DELETE FROM suppliers WHERE supplier_id=?');$s->execute([(int)$_POST['supplier_id']]);flash('success','Supplier deleted.');}}catch(Throwable $e){flash('error','Operation failed: '.$e->getMessage());}redirect('index.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM suppliers WHERE supplier_id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT s.*,COUNT(p.purchase_id) purchase_count,COALESCE(SUM(pi.quantity*pi.unit_cost),0) total_spend FROM suppliers s LEFT JOIN purchases p ON p.supplier_id=s.supplier_id LEFT JOIN purchase_items pi ON pi.purchase_id=p.purchase_id GROUP BY s.supplier_id ORDER BY s.supplier_name')->fetchAll();
require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">PURCHASING NETWORK</p><h1>Suppliers</h1><p class="muted">Store supplier contact details and review purchase history.</p></div></section>
<div class="two-column"><section class="panel"><h2><?= $edit?'Edit supplier':'Add supplier' ?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="supplier_id" value="<?=e($edit['supplier_id']??'')?>"><label class="full">Supplier name<input name="supplier_name" required maxlength="100" value="<?=e($edit['supplier_name']??'')?>"></label><label>Phone<input name="phone" maxlength="15" value="<?=e($edit['phone']??'')?>"></label><label>Email<input name="email" type="email" maxlength="100" value="<?=e($edit['email']??'')?>"></label><label class="full">Address<input name="address" maxlength="200" value="<?=e($edit['address']??'')?>"></label><div class="form-actions full"><button class="btn primary"><?= $edit?'Update supplier':'Add supplier' ?></button><?php if($edit):?><a class="btn secondary" href="index.php">Cancel</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Supplier list</h2><span class="count-label"><?=count($rows)?> total</span></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone / Email</th><th>Purchases</th><th>Total spend</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['supplier_name'])?></strong><small class="subline"><?=e($r['address'])?></small></td><td><?=e($r['phone'])?><small class="subline"><?=e($r['email'])?></small></td><td><?= (int)$r['purchase_count']?></td><td><?=money($r['total_spend'])?></td><td class="actions"><a href="?edit=<?=(int)$r['supplier_id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this supplier? Suppliers with purchases cannot be deleted.');"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="supplier_id" value="<?=(int)$r['supplier_id']?>"><button class="link-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require __DIR__.'/../includes/footer.php';?>
